<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreAppointmentRequest;use App\Http\Requests\RescheduleAppointmentRequest;use App\Services\AppointmentService;use Illuminate\Http\JsonResponse;
class AppointmentController{public function __construct(private AppointmentService $service){}public function store(StoreAppointmentRequest $r):JsonResponse{return response()->json($this->service->create($r->validated()),201);}public function show(string $id):JsonResponse{return response()->json($this->service->get($id));}public function reschedule(RescheduleAppointmentRequest $r,string $id):JsonResponse{return response()->json($this->service->reschedule($id,$r->validated()));}public function cancel(string $id):JsonResponse{return response()->json($this->service->cancel($id));}}